   "card": {
    "fk": "Protoonkgener är normala gener vars produkter främjar celltillväxt, proliferation och överlevnad. Genom mutation eller överuttryck kan de aktiveras till onkgener som verkar dominant (en muterad allel räcker). Tumörsuppressorgener bromsar normalt cellcykeln eller skyddar genomet; de verkar recessivt på cellnivå – båda allelerna måste inaktiveras för att kontrollen ska gå förlorad.",
    "v": [
     "Gatekeepers (bromsar proliferation direkt): RB (håller E2F inaktivt), p53 ('genomets väktare'), p16/INK4A, APC (reglerar β-katenin), PTEN (stänger av PI3K–Akt), NF1.",
     "Caretakers (upprätthåller genomstabilitet): BRCA1/BRCA2 (dubbelsträngsbrott), MSH2/MLH1 (mismatch-reparation), ATM, XP-gener (nukleotidexcisionsreparation).",
     "Punktmutation i kodande region → överaktivt eller oreglerbart protein (t.ex. Ras som inte kan hydrolysera GTP och därför fastnar i 'på-läge').",
     "Genamplifiering → överproduktion (t.ex. HER2 i bröstcancer, N-MYC i neuroblastom).",
     "Kromosomal translokation → antingen förflyttning till en stark enhancer/promotor (t.ex. MYC till Ig-lokus vid Burkitts lymfom; BCL2 till Ig-lokus vid follikulärt lymfom) eller fusionsprotein med nya egenskaper (BCR-ABL vid kronisk myeloisk leukemi, Philadelphiakromosomen)."
    ],
    "k": "",
    "d": "",
    "b": "Retinoblastom (RB1, 13q14): 40 % ärftlig form, 60 % sporadisk; ärftlig form ger förhöjd risk för osteosarkom.",
    "m": "Deletion av hela genen aktiverar aldrig en protoonkgen – det ger förlust av funktion (typiskt för tumörsuppressorer).",
    "src": "t1-256"
   },
