   "card": {
    "fk": "Enzymkopplade (katalytiska) receptorer är transmembrana receptorer som antingen själva har enzymaktivitet i sin cytoplasmatiska del eller är fast associerade med ett enzym. De flesta består av enkla transmembrana kedjor som vid ligandbindning förs samman (oftast dimeriseras) och signalerar genom fosforylering av tyrosinrester. Ligander är tillväxtfaktorer, cytokiner och vissa hormoner (t.ex. insulin).",
    "v": [
     "Varje kedja har tre domäner: ligandbindande extracellulär del (NH₂-terminal), en transmembran α-helix och en cytoplasmatisk effektordel med tyrosinkinasdomän.",
     "Insulinreceptorn är redan en sammanfogad α₂β₂-tetramer (disulfidbindningar) före hormonbindning; insulin aktiverar tyrosinkinaset i β-kedjorna.",
     "Adaptorproteiner med SH2-domäner (binder fosfotyrosin) och SH3-domäner (protein–proteininteraktioner): Grb2, SHC, STAT, PI3-kinas, IRS.",
     "1. Dimerisering och autofosforylering: ligand → kedjorna förs samman → kinasdomänerna aktiverar varandra och fosforylerar tyrosiner på varandras svansar.",
     "2. Dockning: SH2-proteiner binder fosfotyrosinerna → signalkomplex byggs upp; olika receptorer rekryterar olika adaptorer, och signalen delas upp i flera vägar."
    ],
    "k": "",
    "d": "",
    "b": "Tillväxtfaktorreceptorer (EGF-, PDGF-receptorn), src, ras och raf är protoonkogener; överaktivitet ger cancer.",
    "m": "Katalytiska receptorer verkar inte via heterotrimera G-proteiner – det typiska är ändrad fosfotyrosinnivå; nedströms deltar dock små G-proteiner (Ras) och lipidbudbärare (PIP₃).",
    "src": "t1-206"
   },
