   "card": {
    "fk": "IUPAC-nomenklaturen ger organiska molekyler systematiska namn utifrån kolkedjans längd (stam), mättnadsgrad (ändelse), funktionella grupper (prefix/suffix) och substituenternas position. Inom biokemin används dessutom trivialnamn och särskilda numreringssystem (primtecken i nukleotider, Δ- och ω-numrering för fettsyror).",
    "v": [
     "Stamnamn efter antal kol: met (1), et (2), prop (3), but (4), pent (5), hex (6), hept (7), okt (8), non (9), dek (10).",
     "Mättnad: -an (alkan, enkelbindningar), -en (alken, dubbelbindning), -yn (alkyn, trippelbindning).",
     "Numrering: kedjan numreras så att den högst prioriterade funktionella gruppen får lägsta nummer; i karboxylsyror är karboxylkolet C1 (2-hydroxipropansyra = mjölksyra, 2-oxopropansyra = pyruvinsyra).",
     "Grekiska bokstäver: α-kolet är kolet närmast karboxylgruppen (α-aminosyror), β-kolet nästa (β-oxidation, β-hydroxibutyrat).",
     "Fettsyror: 18:1(Δ9) = 18 kol och en dubbelbindning mellan C9 och C10 räknat från karboxyländen; ω-numrering räknas från metyländen (ω-3, ω-6)."
    ],
    "k": "",
    "d": "",
    "b": "Systematiska namn gör att struktur kan härledas ur namnet, vilket behövs för att förstå metabola vägar (t.ex. 3-hydroxi-3-metylglutaryl-CoA, HMG-CoA, i kolesterolsyntesen).",
    "m": "\"-at\" och \"-syra\" är samma molekyl i olika protoneringsgrad (pyruvat/pyruvinsyra).",
    "src": "t1-005"
   },
