   "card": {
    "fk": "Mikrotubuli är cytoskelettets tjockaste filament: ihåliga, polära rör (cirka 25 nm i diameter) av αβ-tubulinheterodimerer ordnade i vanligen 13 protofilament. De utgår från centrosomen, polymeriserar GTP-beroende och växlar ständigt mellan tillväxt och krympning (dynamisk instabilitet). De bildar mitosspindeln, cilier och flageller och utgör spår för intracellulär transport.",
    "v": [
     "Byggsten: heterodimer av α-tubulin och β-tubulin (cirka 8 nm lång). Båda binder GTP; GTP på α-tubulin hydrolyseras aldrig, medan GTP på β-tubulin hydrolyseras efter inbyggnad.",
     "Protofilament: dimerer kopplas ände mot ände i linjära kedjor; 13 protofilament sida vid sida bildar rörväggen.",
     "Polaritet: minusänden (α-tubulin exponerat) är förankrad i centrosomen; plusänden (β-tubulin exponerat) pekar ut mot cellperiferin och växer snabbast.",
     "Nukleation sker på γ-tubulin-ringkomplex i centrosomens pericentriolära material, som fungerar som mall.",
     "Interfas: radiär 'stjärna' från centrosomen."
    ],
    "k": "",
    "d": "",
    "b": "Spindelgifter – både destabiliserande (kolkicin, vinkaalkaloider) och stabiliserande (taxaner, t.ex. paklitaxel) – stoppar celler i mitos (metafas), eftersom spindeln måste vara dynamisk för att fungera.",
    "m": "Mikrotubuli använder GTP (inte ATP) – men motorproteinerna kinesin och dynein hydrolyserar ATP.",
    "src": "t1-260"
   },
