   "card": {
    "fk": "Förbindelser mellan celler (cell junctions) är specialiserade membranområden där cellerna hålls ihop, tätas mot varandra eller kommunicerar. De byggs av transmembrana celladhesionsmolekyler som utanför cellen binder grannens molekyler och inuti cellen kopplar till cytoskelettet via adapterproteiner.",
    "v": [
     "Junktionskomplexet i ett prismatiskt epitel ligger apikalt i ordningen tight junction → adherensförbindelse → desmosom.",
     "Cadheriner: Ca²⁺-beroende, homofil bindning (cadherin–cadherin), långvarig adhesion som håller ihop vävnad; E- (epitel), N- (neuron) och P-cadherin (placenta) samt desmosomala cadheriner.",
     "Selektiner (E-, P-, L-): binder kolhydratligander (t.ex. sialyl-Lewis X) på andra celler; kortvarig adhesion, t.ex. leukocyters rullning på endotel.",
     "Immunglobulinsuperfamiljen (ICAM-1, VCAM-1, CD2 m.fl.): Ca²⁺-oberoende; finjusterar cell–cell-adhesion, binder integriner eller andra IgSF-molekyler.",
     "Integriner: α/β-heterodimerer som medierar både cell–cell- (ligand: IgSF, t.ex. LFA-1–ICAM-1) och cell–ECM-adhesion."
    ],
    "k": "",
    "d": "",
    "b": "Pemfigus: autoantikroppar mot desmogleiner → keratinocyterna släpper från varandra (akantolys) → blåsor. Vulgaris (vanligast, munsår), foliaceus (lindrigast, krustor på bål/skalp, misstas för eksem), paraneoplastisk (svårast, med malignitet).",
    "m": "Desmosomer → intermediära filament; adherensförbindelser → aktin.",
    "src": "t1-284"
   },
