   "card": {
    "fk": "Aminosyror är proteinernas byggstenar. Alla 20 standardaminosyror har en gemensam grundstruktur – en central α-kolatom bunden till en aminogrupp, en karboxylgrupp, en väteatom och en sidokedja (R-grupp) – och skiljer sig åt genom sidokedjan, som bestämmer storlek, laddning och polaritet.",
    "v": [
     "α-kolet är kiralt hos alla utom glycin (R = H). Proteiner byggs av L-aminosyror.",
     "Vid fysiologiskt pH föreligger fria aminosyror som zwitterjoner: −NH₃⁺ och −COO⁻ (pKa för α-COOH ≈ 2, för α-NH₃⁺ ≈ 9–10).",
     "Isoelektrisk punkt (pI): det pH där nettoladdningen är noll.",
     "Glycin: minsta sidokedjan, ger flexibilitet; var tredje rest i kollagen är glycin eftersom bara dess väteatom ryms i trippelhelixens inre (kursboken kap. 2).",
     "Prolin: sidokedjan bildar en ring med kvävet i ryggraden → stel, bryter α-helixar och ger knyckar i kedjan; viktig för kollagenhelixen (kap. 2)."
    ],
    "k": "",
    "d": "",
    "b": "En missense-mutation byter ut en aminosyra mot en annan, t.ex. serin → prolin om kodonet UCA blir CCA (kursboken kap. 9). Effekten beror på hur olika sidokedjorna är.",
    "m": "Glycin är den enda akirala standardaminosyran.",
    "src": "t1-053"
   },
