   "card": {
    "fk": "Mikrofilament är cytoskelettets tunnaste filament (cirka 7–8 nm), byggda av G-aktin (globulärt aktin) som polymeriserar ATP-beroende till polära, dubbelsträngade helikala F-aktin-filament. De dominerar i cellbarken under plasmamembranet och står för cellform, cellrörelse, kontraktion tillsammans med myosin och cytokines.",
    "v": [
     "G-aktin är ett globulärt protein (cirka 42 kDa) som binder ATP (eller ADP) i en klyfta. Sex aktinisoformer finns: fyra muskelspecifika (α-aktiner) och två cytoplasmatiska (β- och γ-aktin) i nästan alla celler. Aktin finns även i cellkärnan.",
     "F-aktin ser ut som två pärlband tvinnade kring varandra; alla monomerer pekar åt samma håll → filamentet har en plusände (barbed end, snabb tillväxt) och en minusände (pointed end, långsam).",
     "ATP-hydrolys: ATP-G-aktin adderas, ATP hydrolyseras strax efter inbyggnaden till ADP + Pi; Pi frisätts och ADP-aktin sitter kvar i filamentet. ADP-aktin har lägre affinitet och lossnar lättare.",
     "Parallella buntar (t.ex. i mikrovilli, filopodier, stressfibrer) och kontraktila buntar med myosin II.",
     "Nätverk/gel i cellbarken och i lamellipodier (grenade nätverk via Arp2/3)."
    ],
    "k": "",
    "d": "",
    "b": "Falloidin (från lömsk flugsvamp, Amanita phalloides) binder och stabiliserar F-aktin och förhindrar depolymerisation; fluorescensmärkt falloidin används för att färga F-aktin i mikroskopi. Svampens livshotande leverskada (efter en symtomfri latens och initial gastroenterit) orsakas främst av amatoxiner (α-amanitin, hämmar RNA-polymeras II) – falloidin tas knappt upp från tarmen.",
    "m": "Aktin kräver ATP, inte GTP (GTP är tubulins nukleotid).",
    "src": "t1-258"
   },
