   "card": {
    "fk": "Under fjärde veckan (med start i slutet av vecka 3) bildas neuralröret genom neurulering, neurallistceller vandrar ut, det paraxiala mesodermet delas upp i somiter, och embryot veckas till en cylindrisk kropp med tarmrör.",
    "v": [
     "Neuralplattan: ektodermet ovanför notokorden förtjockas omkring dag 18 (induktion genom BMP-hämning).",
     "Plattans kanter höjs till neuralveck (neural folds) runt en neuralfåra. Vecken möts och fuserar först i blivande halsregionen (omkring dag 22) och sluts sedan kranialt och kaudalt.",
     "Neuroporerna: kraniala neuroporen sluts omkring dag 25 och kaudala omkring dag 28. Neuralröret blir hjärna och ryggmärg.",
     "Celler vid neuralveckens krön genomgår EMT, lämnar neuroektodermet och vandrar ut i kroppen. Neurallisten kallas ibland det fjärde groddbladet.",
     "Somiter: paraxialt mesoderm delas från omkring dag 20 i parvisa block från kranialt till kaudalt, med ungefär tre par per dag. Totalt bildas cirka 42–44 par. Antalet somiter används för att uppskatta embryots ålder."
    ],
    "k": "",
    "d": "",
    "b": "Neuralrörsdefekter uppstår när neuralröret inte sluts: anencefali (kraniala neuroporen) och spina bifida (kaudalt, från ockulta former till myelomeningocele). Förhöjt alfa-fetoprotein i fostervatten och moderns serum samt ultraljud används i diagnostiken.",
    "m": "Neurallist ≠ neuralrör. Neurallistceller lämnar röret och bildar bl.a. perifera nervsystemets ganglier och Schwannceller, medan CNS (neuroner, astrocyter, oligodendrocyter) kommer från neuralröret.",
    "src": "t1-291"
   },
