   "card": {
    "fk": "Cellcykeln regleras av cykliner och cyklinberoende kinaser (CDK) som tillsammans bildar fasspecifika aktiva kinaskomplex, motverkade av CDK-inhibitorer (CKI) och tumörsuppressorer som RB och p53. Regleringen säkerställer att varje fas fullbordas innan nästa börjar och att cellen bara delar sig när det behövs.",
    "v": [
     "CDK är serin/treonin-kinaser som finns i ungefär konstant mängd genom cykeln men bara är aktiva när rätt cyklin är bundet (och CDK:n bär rätt aktiverande fosforylering).",
     "Cykliner syntetiseras och bryts ned (ubikvitinering → proteasom) i fasspecifika vågor – det är cyklinnivån som ger CDK-aktiviteten dess tidsmönster.",
     "INK4-familjen (t.ex. p16 (INK4A)) hindrar D-cykliner från att binda och aktivera CDK4/6.",
     "CIP/KIP-familjen (t.ex. p21 (CIP1)) hämmar framför allt CDK2-komplex; p21 induceras transkriptionellt av p53.",
     "I vilande celler är RB hypofosforylerat och binder transkriptionsfaktorn E2F (med partnern DP1/2) → S-fasgener hålls avstängda."
    ],
    "k": "",
    "d": "",
    "b": "Ärftligt retinoblastom: nedärvd mutation i RB1 (13q14) → E2F okontrollerat aktiv i retinala celler; ökad risk för osteosarkom senare.",
    "m": "RB är aktivt (bromsande) när det är hypofosforylerat och inaktivt när det är hyperfosforylerat – en klassisk tentafälla.",
    "src": "t1-245"
   },
