     "Tetramer: två dimerer lägger sig antiparallellt och förskjutna → tetrameren saknar polaritet.",
     "Filament: tetramerer associerar sida vid sida och ände mot ände; cirka åtta tetramerer i tvärsnitt tvinnas till ett repliknande filament.",
