     "I G1: ATM/ATR fosforylerar och stabiliserar p53 → p53 inducerar transkription av CKI:n p21 → cyklin–CDK hämmas, RB förblir hypofosforylerat → G1-arrest så att DNA kan repareras.",
     "Om skadan inte kan repareras inducerar p53 apoptos (bl.a. via Bax) – 'genomets väktare'.",
     "I S-fas: replikationshastigheten bromsas; BRCA1 deltar i reparation av dubbelsträngsbrott i ett större komplex.",
     "I G2: ATM/ATR leder till inaktivering av fosfataset cdc25C → inhibitoriska fosfat sitter kvar på CDK1 → cyklin B–CDK1 aktiveras inte → cellen går inte in i mitos med skadat eller ofullständigt replikerat DNA."
