   "card": {
    "fk": "Motorproteiner är mekanokemiska enzymer som omvandlar energin i ATP-hydrolys till rörelse längs cytoskelettfilament. Myosiner går längs aktinfilament, medan kinesiner och dyneiner går längs mikrotubuli – kinesiner oftast mot plusänden (utåt), dyneiner mot minusänden (inåt). De ger kontraktion, organell- och vesikeltransport, kromosomförflyttning och cilierörelse.",
    "v": [
     "Gemensam princip: motordomänen binder nukleotid och filament; ATP-bindning, hydrolys och fosfatfrisättning ger konformationsändringar som får huvudet att släppa, svänga och binda på nytt längre fram (cyklisk bindning).",
     "Myosin binder aktin, hydrolyserar ATP, ändrar konformation (kraftslag), släpper och binder på nytt – cykliskt. Svansen kan fästa vid cellstrukturer som dras med.",
     "Myosin II (dubbelhövdat, bildar bipolära filament) drar antiparallella aktinfilament mot varandra → lokal kontraktion: kontraktil ring vid cytokines, cirkumferentiellt bälte i epitel (sårläkning), stelhet i cellbarken, bakdelens indragning vid migration; i muskel sarkomerkontraktion.",
     "Myosin I och V transporterar last längs aktin (kortväga transport nära cellbarken, mikrovilli).",
     "Kinesinets två huvuden 'går hand över hand' längs ett protofilament; varje steg (cirka 8 nm, en tubulindimer) drivs av en ATP."
    ],
    "k": "",
    "d": "",
    "b": "Primär ciliär dyskinesi / Kartageners syndrom: defekt axonemalt dynein → orörliga cilier → kroniska luftvägsinfektioner, bronkiektasier, manlig infertilitet (orörliga spermier) och i ungefär hälften av fallen situs inversus.",
    "m": "Motorproteinerna hydrolyserar ATP, även de som går på mikrotubuli (som själva binder GTP).",
    "src": "t1-264"
   },
