     "Kinetokorer: proteinkomplex som bildas på varje kromatids centromer och binder kinetokormikrotubuli.",
     "Spindeln utgår från två centrosomer (vardera ett centriolpar) och har tre typer av mikrotubuli: kinetokormikrotubuli (fäster vid kromosomerna), polära mikrotubuli (överlappar i mitten och skjuter isär polerna) och astrala mikrotubuli (strålar ut mot cellbarken och positionerar spindeln).",
