   "card": {
    "fk": "DNA-replikation är kopieringen av cellens hela DNA under S-fasen i cellcykeln. Den är semikonservativ, bidirektionell från många replikationsursprung, kräver en RNA-primer och är semidiskontinuerlig: den nya strängen syntetiseras alltid 5′→3′, kontinuerligt på den ledande strängen och i Okazakifragment på den eftersläpande.",
    "v": [
     "Semikonservativ: varje dotterhelix består av en gammal (parental) och en nysyntetiserad sträng.",
     "Bidirektionell med många origins: replikationen startar samtidigt vid tusentals replikationsursprung (origins) per genom; från varje origin går två replikationsgafflar åt motsatta håll och bildar en replikationsbubbla. Med ca 50 bp/s skulle ett enda ursprung aldrig räcka för 3 × 10⁹ bp.",
     "Primerberoende: DNA-polymeras kan inte starta en kedja från noll – det behöver en fri 3′-OH. Primas lägger en kort RNA-primer som senare tas bort och ersätts med DNA.",
     "Semidiskontinuerlig: polymeraset läser mallen 3′→5′ och syntetiserar 5′→3′. Ledande strängen (leading strand) syntetiseras kontinuerligt i gaffelns rörelseriktning; eftersläpande strängen (lagging strand) syntetiseras bakåt i korta Okazakifragment (100–200 nukleotider hos eukaryoter) som sedan fogas ihop.",
     "1. Initiering: ursprungsigenkännande proteiner binder origin; helikas laddas och öppnar DNA (ATP-beroende)."
    ],
    "k": "",
    "d": "",
    "b": "Cytostatika som hämmar replikation verkar främst på celler i S-fas: antimetaboliter som metotrexat och 5-fluorouracil (minskar dNTP-tillgången) och topoisomerashämmare.",
    "m": "Ingen DNA-polymeras kan syntetisera 3′→5′. Den eftersläpande strängen syntetiseras också 5′→3′ – bara i korta bitar bakåt.",
    "src": "t1-115"
   },
