     "Antaganden: (1) [S] ≫ [E], så att substratbindningen inte märkbart minskar fritt [S]; (2) steady state – [ES] är konstant under mätningen; (3) man mäter begynnelsehastigheten, när produkten är försumbar och bakåtreaktionen kan ignoreras.",
     "Km = (k₋₁ + k₂)/k₁ och Vmax = kcat·[E]_total.",
     "Låg [S] (≪ Km): v₀ ≈ (Vmax/Km)·[S] – första ordningen, hastigheten proportionell mot [S].",
     "[S] = Km: v₀ = Vmax/2."
