    "fk": "Glukoneogenes är nybildning av glukos från icke-kolhydratprekursorer – främst laktat, glycerol och glukogena aminosyror – och sker huvudsakligen i levern och i mindre grad i njurbarken. Syftet är att upprätthålla blodglukos när glykogenförråden inte räcker, så att glukosberoende vävnader (hjärna, erytrocyter, njurmärg) får bränsle.",
