     "Ca 4 H⁺ behövs per ATP som når cytosolen (ca 3 genom ATP-syntas + 1 för transport av Pi och ADP/ATP-utbyte). Därav P/O-kvot ca 2,5 för NADH (10 H⁺) och ca 1,5 för FADH₂ (6 H⁺). Äldre läroböcker anger 3 och 2.",
     "Boken anger upp till ca 32 ATP per glukos i celler med mitokondrier mot 2 ATP i erytrocyter (kap. 5)."
