     "P_Na ökar kraftigt så att den överstiger P_K → enligt GHK går Vm mot E_Na (överskjutning).",
     "Nav-inaktivering: inaktiveringsgrinden stänger inom ca 1 ms trots kvarstående depolarisering.",
     "Fördröjd likriktare (delayed rectifier): spänningsstyrda K⁺-kanaler öppnar långsammare än Nav → K⁺-utflöde repolariserar membranet."
