    "b": "Locusheterogenitet innebär att ett negativt test i en gen inte utesluter ärftlig sjukdom – därför används genpaneler eller exom-/genomsekvensering.",
    "m": "Penetrans = ja/nej (andel sjuka bland bärare); expressivitet = hur mycket. Vanlig tentaförväxling.",
