    "d": "",
    "b": "Extrauterin graviditet: implantation utanför corpus uteri, oftast i äggledaren (ampulla). Den kan ge tubarruptur med livshotande blödning.",
    "m": "Morula = solid kula utan hålighet. Blastocyst = med hålighet (blastocoele). Förväxla inte heller blastocyst med blastula, som är motsvarigheten hos t.ex. groddjur.",
