    "d": "",
    "b": "Trombolys: rekombinant tPA (alteplas) ges vid akut ischemisk stroke och ibland vid lungemboli och hjärtinfarkt för att lösa upp tromber; största risken är blödning.",
    "m": "tPA och uPA aktiverar plasminogen – det är plasmin som är det nedbrytande enzymet.",
