     "Levern saknar succinyl-CoA:acetoacetat-CoA-transferas (tioforas) och kan därför inte själv använda ketonkropparna – de exporteras.",
     "Varför ketogenes? Vid fasta används leverns oxaloacetat för glukoneogenes; acetyl-CoA från β-oxidationen kan då inte kondenseras till citrat i tillräcklig mängd och leds om till ketonkroppar.",
     "Fördelar: vattenlösliga (behöver inga lipoproteiner), passerar blod–hjärnbarriären via monokarboxylattransportörer och ger hjärnan ett alternativ till glukos – vid långvarig svält kan en stor del av hjärnans energi komma från ketonkroppar, vilket minskar behovet av glukoneogenes från muskelprotein."
