     "SID (strong ion difference) = starka katjoner minus starka anjoner, förenklat [Na⁺] + [K⁺] + [Ca²⁺] + [Mg²⁺] − [Cl⁻] − [laktat⁻]; normalt omkring 40 mEq/L. Starka joner är i praktiken helt dissocierade vid fysiologiskt pH.",
     "A_tot – svaga syror som bara delvis dissocierar, framför allt albumin och fosfat.",
     "Beroende variabler ([H⁺], [OH⁻], [HCO₃⁻], [A⁻]) kan inte ändras direkt, bara via de oberoende variablerna."
