     "Insulin/glukagon i levern: glukagon → cAMP → PKA fosforylerar PFK-2/FBPas-2 → fosfatasaktiviteten dominerar → F2,6BP sjunker → glykolys ↓, glukoneogenes ↑. Insulin ger defosforylering → kinasaktiviteten dominerar → F2,6BP stiger → glykolys ↑.",
