    "b": "Används kliniskt för att skatta bärarrisk hos en person utan släkthistoria (se Bärarrisk med Hardy–Weinbergs ekvation).",
    "m": "q² är frekvensen sjuka (vid AR) – ta roten ur för att få q, och bärarfrekvensen är 2q, inte q.",
