    "b": "Läkemedelsinteraktioner: en CYP3A4-hämmare kan ge toxiska nivåer av ett annat läkemedel (t.ex. statiner → myopati); en inducerare kan ge terapisvikt (t.ex. p-piller med rifampicin).",
