    "fk": "En disulfidbindning är en kovalent S–S-bindning mellan tiolgrupperna (–SH) i två cysteinrester, bildad genom oxidation. Den kan förbinda delar av samma polypeptidkedja eller två olika kedjor och stabiliserar proteinets tertiär- och kvartärstruktur. Två cysteiner förenade på detta sätt kallas cystin.",
