     "Klassiska exempel: notokord och primitivknuten → neuralplattan. Ögonblåsan → linsplakoden i ytektodermet. Reciprok induktion mellan uretärknoppen och det metanefrogena mesenkymet → njuren.",
     "Epitel–mesenkymala interaktioner ligger bakom de flesta organanlag (lungor, tänder, körtlar, njure).",
     "Kompetens bestäms av vilka receptorer, signalproteiner och transkriptionsfaktorer cellen har. Därför kan samma signal ge helt olika svar i olika vävnader och vid olika tidpunkter.",
     "Alla vägar slutar i ändrad gentranskription. Signalen aktiverar eller frisätter transkriptionsfaktorer som slår på målgener (jfr signaltransduktion och transkriptionell reglering)."
