     "Tankeexperiment: ett membran som bara släpper igenom K⁺ – K⁺ diffunderar ut längs sin koncentrationsgradient, lämnar anjoner bakom sig och insidan blir negativ. Den växande negativa potentialen drar K⁺ tillbaka, tills ut- och inflöde är lika stora vid E_K."
