     "Ytproteiner: perilipiner (PLIN1–5) som skyddar och reglerar lipolys, lipaser (ATGL), ATGL:s aktivator CGI-58, samt enzymer för triglyceridsyntes.",
     "Storlek: från under 1 µm i de flesta celler till en enda droppe som fyller nästan hela den vita adipocyten (upp till över 100 µm). Bruna adipocyter har många små droppar.",
     "Neutrallipider syntetiseras i ER (DGAT för triglycerider, ACAT för kolesterolestrar) och samlas mellan ER-membranets två blad som en lins."
