     "I läsramen (in-frame, multipel av 3 baser): aminosyror förloras eller läggs till, men resten av proteinet är intakt. Exempel: ΔF508 (p.Phe508del) i CFTR vid cystisk fibros.",
     "Ramförskjutning (frameshift, inte multipel av 3): hela läsramen nedströms ändras, vilket nästan alltid ger ett för tidigt stoppkodon.",
     "Större deletioner/duplikationer: hela exoner eller gener (kopietalsvarianter).",
     "Dynamiska mutationer: expansion av trinukleotidrepetitioner (se trinukleotidsjukdomar)."
