     "Kursboken: stamceller ger först intermediära progenitorceller (transit amplifying cells), som delar sig många gånger och sedan differentierar. Hematopoetiska stamceller väljer i ett första steg mellan en lymfoid och en myeloid progenitor och därefter allt snävare linjer.",
     "Varje steg i commitment beror på ändrat genuttryck. Transkriptionsfaktorer slår på gener för den valda vägen och stänger samtidigt av gener för alternativa vägar."
