     "x": "Prövar hur en dNTP kopplas till växande DNA-sträng; facit anger deoxyribos+bas+3 fosfat på 5'-kol, basparning mot templatet, fosfodiesterbindning till 3'-OH via DNA-polymeras, energi från avklyvt pyrofosfat.",
