     "Kvalitativa sjukdomar (sjuk/frisk) förklaras med tröskelmodellen (liability–threshold model): varje person har en normalfördelad benägenhet (liability); sjukdomen uppstår när benägenheten passerar en tröskel.",
     "Släktingar till en sjuk har förskjuten benägenhetsfördelning (de delar gener och ofta miljö) → fler över tröskeln.",
     "Medfödda missbildningar: läpp-käk-gomspalt, neuralrörsdefekter, de flesta hjärtmissbildningar, pylorusstenos, höftledsdysplasi, Hirschsprungs sjukdom.",
