     "Frisläppta ADP-G-aktin byter ADP mot ATP (främjat av profilin) och kan återanvändas.",
     "GTP-tubulin adderas till plusänden → GTP-kåpa. GTP på β-tubulin hydrolyseras strax efter inbyggnaden; GDP-tubulin i rörets stomme är 'spänt' och hålls kvar bara av kåpan."
