     "Varför RNA-primer: de första nukleotiderna i en kedja kan inte korrekturläsas effektivt (inget stabilt baspar att kontrollera mot). Genom att göra dem av RNA markeras de som ”provisoriska” och byts senare ut mot korrekturläst DNA.",
     "MMR:s strängdiskriminering: reparationssystemet måste veta vilken sträng som är ny; hos eukaryoter används framför allt hack (nicks) i den nya strängen, t.ex. mellan Okazakifragment.",
