     "Uratkristallerna fagocyteras av makrofager och neutrofiler → aktivering av NLRP3-inflammasomen → frisättning av IL-1β → kraftig neutrofil inflammation.",
     "Vid kronisk gikt bildas tofi (uratdepåer i mjukdelar, öronbrosk, senor) och ledskador; urat kan även ge njursten och uratnefropati.",
     "Klinisk bild: akut insättande, intensiv smärta, rodnad, svullnad och värmeökning, ofta nattetid; podagra är klassiskt, men även fotled, knä och handleder drabbas.",
     "Ledpunktion med polarisationsmikroskopi är diagnostisk: nålformade, negativt dubbelbrytande uratkristaller, ofta fagocyterade i neutrofiler."
