     "x": "Prövar hur kooperativitet uppstår i ett protein; facit anger kvartärstruktur med flera subenheter, att bindning i en subenhet via konformationsändring ändrar affiniteten i andra, och sigmoid bindningskurva (som Hb).",
     "k": true,
