     "Hemoglobin: i lungorna (högt pO₂) mättas Hb nästan helt; i vävnaderna (lågt pO₂) ligger man på den branta delen och Hb avger mycket O₂ för en liten sänkning av pO₂. Ett protein med hyperbol kurva och samma halvmättnad skulle avge betydligt mindre."
