   "card": {
    "fk": "Katabolism är nedbrytning av komplexa molekyler till enklare och är som helhet exergon (ΔG < 0); anabolism är uppbyggnad av komplexa molekyler och är endergon. Drivkraften för anabolismen kommer från katabolismen, överförd via ATP och reducerade coenzymer (NADPH), och varje metabol väg har som helhet ett negativt ΔG.",
    "v": [
     "Katabolismen sker i tre faser: hydrolys av makromolekyler till byggstenar, omvandling av byggstenarna till ett fåtal gemensamma intermediärer (främst acetyl-CoA), och slutlig oxidation i citronsyracykeln och oxidativ fosforylering.",
     "Amfiboliska vägar, särskilt citronsyracykeln, fungerar både kataboliskt och som källa till prekursorer för syntes.",
     "Energetisk koppling: endergona syntessteg kopplas till ATP-hydrolys (eller GTP, UTP, CTP), så att nettoreaktionen får negativt ΔG.",
     "Reduktionskraft: katabolismen ger NADH (används främst för ATP-syntes i andningskedjan), medan anabolismen använder NADPH (från bl.a. pentosfosfatshunten).",
     "Irreversibla steg med stort negativt ΔG ger metabola vägar en riktning. Om en väg och dess omvända väg använde samma enzymer skulle de inte kunna styras oberoende och flödet skulle bestämmas enbart av massverkan."
    ],
    "k": "",
    "d": "",
    "b": "Vid diabetes mellitus typ 1 saknas insulin → katabolismen dominerar: glykogenolys, glukoneogenes, lipolys och ketogenes ger hyperglykemi och risk för ketoacidos.",
    "m": "Anabola vägar är inte bara katabola vägar baklänges – de irreversibla stegen sköts av andra enzymer.",
    "src": "t1-040"
   },
