    "d": "",
    "b": "Hjärtglykosider (digoxin) minskar Na⁺-gradienten → Na⁺/Ca²⁺-växlaren får mindre drivkraft → intracellulärt Ca²⁺ stiger → ökad kontraktionskraft (bokens klinikruta).",
    "m": "En jon kan flöda mot sin koncentrationsgradient genom en kanal om den elektriska kraften är större (t.ex. Cl⁻ i vissa celler) – det är den elektrokemiska gradienten som gäller.",
