     "Enzymets pH-optimum är ofta anpassat till miljön där det verkar. Lysosomens insida är surare än cytosolen (pH 4,8 jämfört med 7,2); de lysosomala enzymerna är därför nästan inaktiva om de läcker ut i cytosolen – ett skydd mot okontrollerad nedbrytning (kursboken kap. 12)."
