    "fk": "Det nukleära genomet är fördelat på kromosomer. Varje kromosom är en enda lång, linjär dubbelsträngad DNA-molekyl packad med histoner och andra proteiner till kromatin. Människans somatiska celler är diploida med 46 kromosomer (22 par autosomer + två könskromosomer, XX eller XY), och könscellerna är haploida med 23.",
