     "Hemoglobin A (vuxet): två α- och två β-kedjor, var och en med Mb-liknande veckning och ett hem – totalt fyra O₂-bindningsställen. Starka kontakter inom varje αβ-dimer, svagare mellan dimererna som rör sig vid O₂-bindning.",
     "Två konformationer: T (tense) – deoxyform med låg affinitet, stabiliserad av jonbindningar mellan dimererna; R (relaxed) – oxyform med hög affinitet.",
     "Kooperativitet: när O₂ binder ett hem dras järnet in i porfyrinplanet och drar med sig proximala histidinet och dess helix → konformationsändringen förs vidare till de andra subenheterna och T→R-övergången underlättas. Den sigmoida kurvan gör att Hb mättas i lungorna men avger mycket O₂ i vävnaderna."
