     "Upptäcktes hos bananflugan (Drosophila) genom homeotiska mutationer, där ett segment får ett annat segments identitet. Antennapedia-mutanter har ben i stället för antenner, och bithoraxmutanter får ett extra vingpar.",
     "Människan har 39 HOX-gener i fyra kluster: HOXA (kromosom 7), HOXB (17), HOXC (12) och HOXD (2). Generna fördelar sig på 13 paraloga grupper.",
     "De fyra klustren har uppstått genom duplikationer av ett ursprungligt kluster och är ett skolexempel på en genfamilj (se genfamiljer). Generna är starkt konserverade mellan flugor och däggdjur.",
     "Kolinearitet: generna ligger i samma ordning i klustret som de uttrycks längs kroppen. 3′-gener (paralog 1–4) uttrycks mer kranialt och tidigare, 5′-gener (9–13) mer kaudalt och senare (spatial och temporal kolinearitet)."
