    "fk": "Meios är den specialiserade celldelning i könscellslinjen där en replikationsomgång följs av två delningar (meios I och II), så att en diploid cell (2n) ger upphov till fyra haploida (n), genetiskt olika celler. Meiosen halverar kromosomtalet och skapar genetisk variation genom överkorsning och oberoende fördelning.",
