     "Andra lagen: ΔS(universum) = ΔS(system) + ΔS(omgivning) > 0 för en spontan process. Ordning kan alltså uppstå lokalt (t.ex. ett veckat protein, en cell) bara om oordningen i omgivningen ökar mer.",
