     "Relativa permeabiliteter i vila (klassiskt värde från bläckfiskaxon): P_K : P_Na : P_Cl ≈ 1 : 0,04 : 0,45.",
     "Uppkomst i två steg: (1) Na⁺/K⁺-pumpen bygger upp jongradienterna; (2) K⁺ läcker ut genom öppna K⁺-kanaler och lämnar negativa, icke-permeabla anjoner kvar → insidan blir negativ.",
     "Eftersom membranet också läcker lite Na⁺ dras potentialen från E_K (ca −90 mV) mot E_Na → vilopotentialen i neuron blir ca −70 mV. Beräknas med GHK-ekvationen.",
