    "fk": "Ämnesomsättningens centrala coenzymer är små organiska molekyler, oftast härledda från vattenlösliga B-vitaminer, som bär elektroner (NAD⁺, NADP⁺, FAD, FMN), acylgrupper (coenzym A, liponsyra) eller andra kemiska grupper (TPP, biotin, PLP, folat, B12) mellan enzymreaktioner.",
